#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
Reemplaza el logo actual por el nuevo logo de Only Enterprises,
y actualiza el nombre de la marca en toda la app.
Uso: cd ~/inventario && python3 cambiar_logo.py
"""
import os, re, base64

STATIC = os.path.expanduser('~/inventario/static')

LOGO_B64 = ''

# ================================================================
# 1. Reemplazar el archivo del logo
# ================================================================
print("1. Reemplazando static/logo.png...")
logo_path = os.path.join(STATIC, 'logo.png')
with open(logo_path, 'wb') as f:
    f.write(base64.b64decode(LOGO_B64))
print("   OK logo.png actualizado (" + str(os.path.getsize(logo_path)) + " bytes)")

# ================================================================
# 2. Reemplazar el nombre "OnlyReef" -> "Only Enterprises" en todas las paginas
# ================================================================
print("2. Actualizando el nombre de la marca en todas las paginas...")
archivos = [f for f in os.listdir(STATIC) if f.endswith('.html')]
total_cambios = 0

for archivo in archivos:
    ruta = os.path.join(STATIC, archivo)
    src = open(ruta, encoding='utf-8').read()
    original = src

    src = src.replace('OnlyReef', 'Only Enterprises')
    src = src.replace('onlyreef', 'only_enterprises')  # claves internas de sessionStorage, etc.

    if src != original:
        open(ruta, 'w', encoding='utf-8').write(src)
        cambios = original.count('OnlyReef') + original.count('onlyreef')
        total_cambios += cambios
        print("   OK " + archivo + ": " + str(cambios) + " referencia(s) actualizadas")

print("   Total: " + str(total_cambios) + " referencias actualizadas en " + str(len(archivos)) + " archivos")

print()
print("=" * 50)
print("Reiniciando el servicio...")
os.system("sudo systemctl restart inventario")
print("Listo. Refresca la app (Cmd+Shift+R) para ver el nuevo logo y nombre.")
